-- End-of-lesson checks: 3 multiple-choice questions and 1 reflection for each
-- daily lesson (120 BaseCamp, 4 My Path). Re-running replaces the questions
-- for these lessons. Attempts, passes and reflections on removed questions go
-- with them, so only re-run before anyone has started.
begin;

-- basecamp 1: Monday: Why we exist
delete from public.quiz_questions where task_id = (select id from public.tasks where week_n = 1 and kind = 'lesson' and title = $q$Monday: Why we exist$q$);
with ins as (insert into public.quiz_questions (task_id, sort, kind, prompt, choices) select id, 1, 'mc', $q$Who is District H mainly built to serve?$q$, $q$["Competitive athletes chasing peak performance", "People who are sick and need clinical care", "Busy adults in the middle who want a routine that lasts", "Committed lifters who want the newest program"]$q$::jsonb from public.tasks where week_n = 1 and kind = 'lesson' and title = $q$Monday: Why we exist$q$ returning id)
  insert into public.quiz_keys (question_id, correct) select id, 2 from ins;
with ins as (insert into public.quiz_questions (task_id, sort, kind, prompt, choices) select id, 2, 'mc', $q$According to the lesson, what part of coaching can't be automated?$q$, $q$["Writing a well-designed training program for each member", "Helping someone change how they live, and holding them to it over years", "Choosing the right sets, reps, and loads for the day", "Tracking attendance and logging every member's results"]$q$::jsonb from public.tasks where week_n = 1 and kind = 'lesson' and title = $q$Monday: Why we exist$q$ returning id)
  insert into public.quiz_keys (question_id, correct) select id, 1 from ins;
with ins as (insert into public.quiz_questions (task_id, sort, kind, prompt, choices) select id, 3, 'mc', $q$What is BaseCamp?$q$, $q$["A short certification course that interns pay tuition for", "An onboarding program that helps new members get started", "A trial period before a part-time side role on the floor", "A paid trade apprenticeship, the first stretch of a five-year climb"]$q$::jsonb from public.tasks where week_n = 1 and kind = 'lesson' and title = $q$Monday: Why we exist$q$ returning id)
  insert into public.quiz_keys (question_id, correct) select id, 3 from ins;
insert into public.quiz_questions (task_id, sort, kind, prompt) select id, 4, 'short', $q$Think of someone you know who fits the middle group. What has kept them from sticking with a routine, and what would a coach need to do to help them stay?$q$ from public.tasks where week_n = 1 and kind = 'lesson' and title = $q$Monday: Why we exist$q$;

